SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
    SELECT arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__', 'instance'], tag.1), tags)) AS tags, timestamp AS timestamp, if(countIf(isNaN(value)) > 0 OR count() = 0, CAST(NULL, 'Nullable(Float64)'), avg(value)) AS value FROM (
        SELECT arrayFilter(tag -> tag.1 != '__name__', tags) AS tags, eval_ts AS timestamp, if(arrayExists(v -> isNaN(v), window_values) OR (window_duration_ms) <= 0, nan, (counter_delta_sum) * (if((((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))) <= 0, 1.0, (((((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))) + (if(((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))) - ((toFloat64(toUnixTimestamp64Milli(eval_ts))) - 300000.0)) < ((((((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))) / greatest(toFloat64(length(window_series)) - 1, 1))) * 1.1), ((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))) - ((toFloat64(toUnixTimestamp64Milli(eval_ts))) - 300000.0)), (((((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))) / greatest(toFloat64(length(window_series)) - 1, 1))) / 2)) + (if(((toFloat64(toUnixTimestamp64Milli(eval_ts))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series)))))) < ((((((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))) / greatest(toFloat64(length(window_series)) - 1, 1))) * 1.1), ((toFloat64(toUnixTimestamp64Milli(eval_ts))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series)))))), (((((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))) / greatest(toFloat64(length(window_series)) - 1, 1))) / 2)))) / (((toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, length(window_series))))) - (toFloat64(toUnixTimestamp64Milli(arrayElement(window_timestamps, 1)))))))) / (300)) AS value FROM (
            SELECT source.tags AS tags, grid.eval_ts AS eval_ts, arrayFilter(point -> tupleElement(point, 1) <= grid.eval_ts - toIntervalMillisecond(0) AND tupleElement(point, 1) >= grid.eval_ts - toIntervalMillisecond(300000), source.time_series) AS window_series, arrayMap(point -> tupleElement(point, 1), window_series) AS window_timestamps, arrayElement(window_timestamps, length(window_series)) - arrayElement(window_timestamps, 1) AS window_duration_ms, arrayMap(point -> ifNull(toFloat64(tupleElement(point, 2)), nan), window_series) AS window_values, arraySum(arrayMap((p, c) -> if(c < p, c, c - p), arrayPopBack(window_values), arrayPopFront(window_values))) AS counter_delta_sum FROM (SELECT arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range(1700000000000, 1700000300000 + 1, 60000))) AS eval_ts) AS grid CROSS JOIN (
                SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
                    SELECT series.tags AS tags, d.timestamp AS timestamp, d.value AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
                        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {range_matrix_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({required_end_ms:Int64})
                    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({required_end_ms:Int64}) AND reinterpretAsUInt64(d.value) != 9218868437227405314 AND d.id IN (SELECT id FROM (
                        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {range_matrix_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({required_end_ms:Int64})
                    ))
                ) GROUP BY tags
            ) AS source
        ) AS step_windows WHERE length(window_series) > 1
    ) GROUP BY tags, timestamp
) GROUP BY tags ORDER BY tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
